-- Carga de 161 cinemas lidos das páginas salvas do AdoroCinema
-- (Cinema em <cidade>, 21 cidades; só a 1ª página de cada listagem foi salva, então
-- cidades grandes aparecem incompletas). Script avulso: não faz parte das
-- migrations; rode quando quiser, quantas vezes quiser.
--
--   psql "$DATABASE_URL" -f scripts/seed_cinemas.sql
--
-- Não apaga nada: é um upsert. Os IDs são UUIDv5 do link do cinema no
-- AdoroCinema (namespace URL), então são estáveis entre execuções e uma nova
-- carga atualiza nome/endereço/logo sem tocar em salas e sessões existentes.
-- `logo_url` é a URL remota do logo (acsta.net); NULL se a página não traz logo.
-- Salas não são criadas: as páginas só informam a quantidade, não tipo de tela
-- nem capacidade.
ON CONFLICT (id) DO UPDATE SET
    nome = EXCLUDED.nome,
    cidade = EXCLUDED.cidade,
    estado = EXCLUDED.estado,
    endereco = EXCLUDED.endereco,
    logo_url = EXCLUDED.logo_url,
    atualizado_em = CURRENT_TIMESTAMP;
